modules.push(...[{"id": "subjonctif", "n": "11", "title": "Le subjonctif présent", "subtitle": "Former le subjonctif et choisir le mode", "lessons": [9, 10, 11, 13], "tag": "Conjugaison", "color": "teal", "intro": "Exprimer une volonté, un sentiment, un doute ou une nécessité.", "sections": [["Deux bases, puis les irréguliers", "<p>Pour je, tu, il et ils : pars de <b>ils au présent sans -ent</b>, puis ajoute <b>-e, -es, -e, -ent</b>. Pour nous et vous : utilise la base de nous au présent avec <b>-ions, -iez</b>.</p><div class=\"example\">Ils prennent → que je <b>prenne</b>, qu’ils <b>prennent</b>.<br>Nous prenons → que nous <b>prenions</b>, que vous <b>preniez</b>.<br>Ils boivent / nous buvons → qu’il <b>boive</b>, que nous <b>buvions</b>.</div><p>Être et avoir ont des terminaisons particulières : <b>sois, sois, soit, soyons, soyez, soient</b> ; <b>aie, aies, ait, ayons, ayez, aient</b>. Autres formes : que je fasse, puisse, sache, veuille, aille ; que nous fassions, puissions, sachions, voulions, allions. Falloir : <b>qu’il faille</b>. Voir les six personnes dans le <a href=\"#verbes\">répertoire</a>.</p>"], ["Les déclencheurs utiles", "<table><tr><th>Usage</th><th>Construction</th></tr><tr><td>Volonté</td><td>Je souhaite / je veux / j’aimerais que tu viennes.</td></tr><tr><td>Sentiment</td><td>Je suis content qu’elle soit là. Je crains qu’il parte.</td></tr><tr><td>Nécessité</td><td>Il faut / il est important que nous finissions.</td></tr><tr><td>Doute</td><td>Je ne pense pas qu’il ait raison.</td></tr><tr><td>But</td><td>Je répète pour que vous compreniez.</td></tr><tr><td>Concession</td><td>Bien qu’il soit fatigué, il continue.</td></tr></table><p>Autres conjonctions du cours : <b>avant que, en attendant que, jusqu’à ce que, à condition que, à moins que, pourvu que, afin que</b>. Le <i>ne</i> de « avant qu’il ne parte » peut être explétif : il ne signifie pas une négation.</p>"], ["Indicatif, subjonctif ou infinitif ?", "<div class=\"example\">Je pense qu’elle <b>vient</b>. Je ne pense pas qu’elle <b>vienne</b>.<br>J’espère qu’elle <b>viendra</b>.<br>Je souhaite <b>partir</b>. Je souhaite qu’elle <b>parte</b>.<br>Il faut <b>réviser</b>. Il faut que tu <b>révises</b>.</div><p>Affirmatifs : penser, croire, trouver, constater, savoir et espérer prennent normalement l’indicatif. Une appréciation change la construction : <b>je trouve qu’il est gentil</b>, mais <b>je trouve normal qu’il soit ici</b>. Avec le même sujet, préférer l’infinitif après souhaiter ou vouloir.</p><p>Le subjonctif n’est pas simplement « l’incertitude » : on peut être content d’un fait certain. La construction et le sens gouvernent le choix. <b>Il est certain que</b> et <b>après que</b> prennent l’indicatif. <b>De sorte que</b> prend le subjonctif pour un but voulu, l’indicatif pour une conséquence constatée.</p>"], ["Le temps du verbe principal", "<p>Le subjonctif présent peut suivre un verbe principal au présent, au passé ou au futur : <b>j’attends / j’ai attendu / j’attendrai qu’elle soit prête</b>. Le choix du temps dans la subordonnée dépend du sens. La forme ne devient pas automatiquement un passé parce que le verbe principal est au passé.</p>"]], "en": "Mood is governed by constructions and meaning. Recognition of triggers does not establish independent conjugation or spoken use. The handout typo “il faut que + infinitif” is corrected here.", "source": "Cours 9 : LE SUBJONCTIF INTRO.pdf p. 1, LE SUBJONCTIF 1.docx p. 1 ; cours 10 : LE SUBJONCTIF 2.docx p. 1 ; cours 13 : OPINIONS.docx p. 3. Exercices nouveaux.", "q": [["Il faut que nous ___ (prendre) le tram.", "prenions", "Base de nous prenons + ions."], ["Je souhaite que tu ___ (être) disponible.", "sois", "Être : que tu sois."], ["J’espère qu’elle ___ demain.", "viendra", "Espérer affirmatif est normalement suivi de l’indicatif.", ["vienne", "viendra"]], ["Je suis heureux que vous ___ (avoir) du temps.", "ayez", "Avoir : que vous ayez."], ["Je révise pour que tout ___ (aller) bien.", "aille", "Aller : que tout aille."], ["Il faut ___ avant midi.", "partir", "Il faut + infinitif, sans que.", ["partir", "que partir"]]]}, {"id": "opinions", "n": "12", "title": "Exprimer son opinion", "subtitle": "Affirmer, nuancer et réagir", "lessons": [10, 13], "tag": "Communication", "color": "teal", "intro": "Construire un avis et le défendre avec une raison et un exemple.", "sections": [["Des expressions qui changent le mode", "<div class=\"example\"><b>À mon avis</b>, ce projet est utile.<br><b>Je pense que</b> ce projet est utile.<br><b>Je ne pense pas que</b> ce projet soit inutile.<br><b>Je ne suis pas sûr que</b> cette solution convienne.</div><p>Sans que : <b>selon moi, de mon point de vue, en ce qui me concerne</b>. Avec indicatif : je crois que, je suppose que, je considère que, je suis certain que. Avec subjonctif dans les modèles du cours : je ne crois pas que, je ne trouve pas que, je ne suis pas sûr que.</p>"], ["Une réponse structurée", "<p><b>Position → raison → exemple → nuance.</b> Utilise d’abord, parce que, par exemple, cependant, d’un côté et de l’autre, enfin. Pour réagir : <b>je comprends ton point de vue, mais… ; je suis d’accord sur ce point ; je ne partage pas cet avis.</b></p><div class=\"example\">À mon avis, travailler près de chez soi est un avantage parce qu’on perd moins de temps dans les transports. Par exemple, on peut rentrer déjeuner. Cependant, le poste doit aussi correspondre à ses compétences.</div>"], ["À pratiquer sans corrigé automatique", "<p>Choisis une question : la semaine de quatre jours, les téléphones à l’école, les voitures électriques ou le FCC. Présente un avantage, un inconvénient, ton avis et un exemple. Puis réponds à une objection.</p><p><b>Devoir 6 :</b> répondre à une amie qui hésite à partir travailler à l’étranger. Le document demande <b>120–150 mots</b>, une opinion et des exemples d’expériences. Garde ton propre texte ; aucun modèle de réponse au devoir n’est dévoilé ici.</p><p>Pour une image : décris d’abord ce qui est visible, puis distingue ton interprétation. Lexique du cours : le saut à l’élastique, les bains glacés, la chirurgie esthétique ; courageux, dangereux, inutile, cher.</p>"]], "en": "Use the indicative for an asserted opinion and normally the subjunctive in the negative opinion patterns practised here. The 120–150-word requirement belongs to homework 6, not a confirmed exam writing limit.", "source": "Cours 10 : LES EXPRESSIONS DE L.docx pp. 1–3 ; cours 13 : OPINIONS.docx pp. 1–3 ; B1- DEVOIR 6.docx p. 1. Exercices nouveaux.", "q": [["Je ne pense pas qu’il ___ (pouvoir) venir.", "puisse", "Je ne pense pas que + subjonctif."], ["Je trouve normal que chacun ___ (donner) son avis.", "donne", "Une appréciation : trouver normal que + subjonctif."], ["___ moi, il faut changer les horaires.", "selon", "Selon moi ne prend pas que."], ["Je suis certain que cette idée ___ utile.", "est", "La certitude affirmative appelle l’indicatif.", ["est", "soit"]]]}, {"id": "conditionnel", "n": "13", "title": "Le conditionnel présent", "subtitle": "Demandes, souhaits et conseils", "lessons": [11, 12], "tag": "Conjugaison", "color": "teal", "intro": "Adoucir une demande, exprimer un souhait et proposer une solution.", "sections": [["La formation", "<p><b>Base du futur + terminaisons de l’imparfait : -ais, -ais, -ait, -ions, -iez, -aient.</b> Pour les verbes réguliers, partir de l’infinitif ; enlever le e final des verbes en -re.</p><div class=\"example\">parler → je <b>parlerais</b> ; finir → nous <b>finirions</b> ; attendre → vous <b>attendriez</b>.</div><table><tr><th>Verbe</th><th>Base</th><th>Exemple</th></tr><tr><td>être / avoir</td><td>ser- / aur-</td><td>je serais / j’aurais</td></tr><tr><td>aller / faire</td><td>ir- / fer-</td><td>tu irais / tu ferais</td></tr><tr><td>pouvoir / vouloir</td><td>pourr- / voudr-</td><td>vous pourriez / vous voudriez</td></tr><tr><td>devoir / savoir</td><td>devr- / saur-</td><td>elle devrait / elle saurait</td></tr><tr><td>venir / voir</td><td>viendr- / verr-</td><td>ils viendraient / ils verraient</td></tr></table><p>Les bases irrégulières sont un complément de référence à la règle du cours. Retrouvez les six personnes dans le répertoire des verbes.</p>"], ["Quatre intentions", "<table><tr><th>Intention</th><th>Exemple</th></tr><tr><td>Demande polie</td><td>Pourriez-vous m’envoyer le document ?</td></tr><tr><td>Souhait</td><td>J’aimerais mieux comprendre cette règle.</td></tr><tr><td>Conseil</td><td>Tu devrais prendre une pause.</td></tr><tr><td>Suggestion</td><td>On pourrait en parler demain.</td></tr></table><div class=\"example\"><b>À votre place, je vérifierais</b> les horaires.<br>Je <b>ferais bien</b> une promenade.</div>"], ["Demander un service au travail", "<p>Précise le besoin, propose une solution et remercie. Pour accepter : <b>ça me va ; je suis d’accord ; ça m’arrange</b>. Pour refuser : <b>je suis désolé, je ne peux pas ; j’aimerais bien, mais…</b></p><p>Lexique de la lecture : <b>poser un jour de congé, remplacer quelqu’un, échanger un jour de travail, mettre quelqu’un en copie, c’est réglé</b>. Exprime la raison avec parce que, comme ou en raison de ; la conséquence avec donc ou par conséquent.</p>"], ["À distinguer", "<div class=\"example\">Demain, je <b>partirai</b> tôt. (futur)<br>À ta place, je <b>partirais</b> tôt. (conditionnel)<br>Avant, je <b>partais</b> tôt. (imparfait)</div><p>Ne confonds pas la base du futur et la base de l’imparfait. Complément utile : pour une hypothèse, <b>si + imparfait → conditionnel</b> : si j’avais le temps, je viendrais. Pas de conditionnel après si dans cette construction.</p>"]], "en": "Use the future stem with imperfect endings. Present conditional expresses politeness, wishes and advice. The si pattern is a supporting reference rather than a dedicated supplied worksheet.", "source": "Cours 11 : remplacement.pdf p. 1 ; cours 12 : LE CONDITIONNEL 1 (1).pdf p. 1, LE CONDITIONNEL.pdf p. 1. Exercices nouveaux.", "q": [["Vous ___ (pouvoir, conditionnel) répéter la question ?", "pourriez", "Pourr- + iez."], ["À ta place, je ___ (faire) une pause.", "ferais", "Fer- + ais."], ["Nous ___ (aimer, conditionnel) visiter Lyon.", "aimerions", "Aimer- + ions."], ["Tu ___ (devoir, conditionnel) lui écrire.", "devrais", "Devr- + ais."], ["Je ___ (être, conditionnel) disponible lundi.", "serais", "Ser- + ais."]]}, {"id": "reproches", "n": "14", "title": "Reproches et malentendus", "subtitle": "Réagir et proposer une autre réponse", "lessons": [11, 12, 13], "tag": "Communication", "color": "teal", "intro": "Expliquer ce qui ne va pas et dire ce qui aurait été préférable.", "sections": [["Une réaction avec le subjonctif", "<div class=\"example\"><b>Comment se fait-il que</b> tu sois encore au bureau ?<br>J’ai besoin que nous <b>soyons</b> clairs.<br>Je regrette que cette réponse <b>soit</b> ambiguë.</div><p>Comment se fait-il que… ? exprime l’étonnement, parfois un reproche. Le ton compte : pour ouvrir une discussion, on peut commencer par <b>je voudrais comprendre ce qui s’est passé</b>.</p>"], ["Le conditionnel passé rencontré dans le cours", "<p>Le script du cours 13 contient <b>j’aurais dû répondre, tu aurais fait, j’aurais dit</b>. Il s’agit du conditionnel passé. Repère : <b>avoir ou être au conditionnel + participe passé</b>. La formation complète ci-dessous est un complément explicatif au script, pas une nouvelle fiche du professeur.</p><div class=\"example\">Tu <b>devrais prévenir</b> ton équipe. (conseil maintenant)<br>Tu <b>aurais dû prévenir</b> ton équipe. (reproche sur le passé)<br>À ta place, j’<b>aurais demandé</b> une précision.<br>Elle <b>serait venue</b>, mais elle était malade.</div><p>Les règles d’auxiliaire et d’accord des temps composés restent valables. Le conditionnel peut aussi exprimer un futur vu depuis le passé : <b>il a dit qu’il viendrait</b>. Ce n’est pas forcément un souhait.</p>"], ["Expliquer le problème sans accuser", "<p><b>Un malentendu, une date butoir, un délai, rendre un projet, avancer une date, laisser entendre, dire franchement, tenir le même discours.</b></p><p>Décris les faits, explique ton interprétation, puis propose une solution : <b>j’avais compris que… ; ce n’était pas mon intention ; je me suis mal exprimé ; la prochaine fois, on pourrait…</b></p><p>Exercice oral libre : un collègue pense que tu as accepté une tâche, mais tu voulais seulement vérifier ta disponibilité. Clarifie le malentendu et propose une meilleure façon de répondre.</p>"]], "en": "The past conditional is attested in the supplied transcript. The fuller formation explanation is supporting reference. This page contains no listening task or transcript answers.", "source": "Cours 11 : MYLENE - SUBJ- CO15.docx pp. 1–2 ; cours 13 : reproches transcription.pdf p. 1. Le script a été lu ; l’audio n’a pas été vérifié. Exercices nouveaux.", "q": [["Comment se fait-il que vous ___ (être) en retard ?", "soyez", "Comment se fait-il que + subjonctif."], ["Tu ___ dû vérifier hier. (avoir, conditionnel)", "aurais", "Aurais dû : conditionnel passé de devoir."], ["À sa place, nous ___ demandé une explication. (avoir, conditionnel)", "aurions", "Aurions demandé : conditionnel passé."]]}, {"id": "doubles", "n": "15", "title": "Les doubles pronoms", "subtitle": "Ordre, placement et accords", "lessons": [13, 14], "tag": "Grammaire", "color": "teal", "intro": "Remplacer deux compléments sans perdre leur rôle dans la phrase.", "sections": [["L’ordre avant le verbe", "<table><tr><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th></tr><tr><td>me, te, se, nous, vous</td><td>le, la, les</td><td>lui, leur</td><td>y</td><td>en</td></tr></table><p>Ce tableau indique l’ordre des combinaisons possibles, pas une invitation à tout combiner.</p><div class=\"example\">Elle donne le dossier à Paul → elle <b>le lui</b> donne.<br>Elle donne le dossier à moi → elle <b>me le</b> donne.<br>Je parle du projet à mes collègues → je <b>leur en</b> parle.<br>Je m’intéresse à ce projet → je <b>m’y</b> intéresse.</div>"], ["Verbe, auxiliaire et infinitif", "<div class=\"example\">Je <b>ne le lui donne pas</b>.<br>Je <b>le lui ai donné</b>.<br>Je <b>vais le lui donner</b>.<br>Je <b>ne peux pas le lui donner</b>.</div><p>Au temps composé, les pronoms précèdent l’auxiliaire. Avec un infinitif, ils précèdent normalement le verbe dont ils dépendent. À l’impératif affirmatif, la disposition change : <b>donne-le-moi</b>. Ce dernier cas est un complément de référence ; à l’impératif négatif : <b>ne me le donne pas</b>.</p>"], ["Accord et référents", "<div class=\"example\">La lettre ? Je <b>la lui ai envoyée</b>.<br>Les dossiers ? Elle <b>me les a montrés</b>.</div><p>Avec avoir, le participe s’accorde avec le COD placé avant : la = lettre, les = dossiers. <b>Lui/leur</b> sont COI et ne commandent pas cet accord. Pour vérifier, rétablis les noms et repère le verbe.</p><p>En remplace notamment une quantité : <b>des copies, je lui en ai donné deux</b>. Le participe reste normalement invariable avec en.</p>"], ["Y et en peuvent se suivre", "<p>La fiche du professeur donne une interdiction trop absolue. <b>Y + en</b> est possible au-delà de « il y en a » : <b>des livres dans ce sac, j’y en ai mis deux</b>. Retenir l’ordre y puis en, en s’assurant que chacun remplace un complément clair.</p>"]], "en": "Third-person lui/leur follows le/la/les, whereas me/te/nous/vous comes before them. Identify the direct object before applying past-participle agreement. The absolute y/en prohibition in the handout is corrected.", "source": "Cours 13 : Pronoms révision.docx p. 1, Les pronoms récapitulatif.pdf p. 1 ; cours 14 : B1 - LES DOUBLES PRONOMS.pdf pp. 1–2. Exercices nouveaux.", "q": [["Je donne le dossier à Léa. → Je ___ donne.", "le lui", "Le dossier = le ; à Léa = lui."], ["Elle montre les photos à moi. → Elle ___ montre.", "me les", "Me précède les."], ["Nous parlons du projet à nos voisins. → Nous ___ parlons.", "leur en", "À nos voisins = leur ; du projet = en."], ["La carte ? Je la lui ai ___ (envoyer).", "envoyée", "La reprend carte, féminin singulier, COD avant avoir."], ["Je vais donner le livre à Paul. → Je vais ___ donner.", "le lui", "Les pronoms précèdent donner, dont ils dépendent."]]}]);

